-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('08299acd-f715-5459-8a34-0dcdd22336cf'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, 'Comment s’écrit une question en espagnol ?', 'mcq', '["Avec un ¿ à l’ouverture et un ? à la fermeture","Avec un seul ? final","Avec un ¿ seulement","Avec « est-ce que » puis un ?"]'::jsonb, 0, 'Le ¿ se place au début de la partie interrogée, pas forcément de la phrase.', 1),
    ('40d8f57c-ed3c-5ab4-88d5-04313524cc94'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, 'Les mots interrogatifs espagnols portent tous un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est lui qui distingue *dónde* (interrogatif) de *donde* (relatif).', 2),
    ('a8142cec-8daf-523d-91a8-e3b673cadf97'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, 'Que demande « cuál » plutôt que « qué » ?', 'mcq', '["Un choix dans un ensemble","Une définition","Une cause","Une quantité"]'::jsonb, 0, '*¿Cuál prefieres?* suppose plusieurs possibilités déjà connues.', 3),
    ('73d2c2c9-34f3-5716-aaee-ec63f63c3712'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, 'Comment traduire « Pourquoi pleures-tu ? » ?', 'mcq', '["¿Por qué lloras?","¿Porque lloras?","¿Porqué lloras?","¿Por que lloras?"]'::jsonb, 0, 'En deux mots et avec l’accent : c’est la question, pas la réponse.', 4),
    ('be7fb5e5-9180-50d1-9598-a3d1acd11825'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, '« El porqué » est un nom masculin qui signifie « la raison ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*No entiendo el porqué de su decisión.*', 5),
    ('968aa0c2-0a0c-5c85-82e5-23ae433552b6'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, 'Dans « No sé dónde está », l’accent sur « dónde »…', 'mcq', '["Se maintient malgré l’absence de point d’interrogation","Disparaît","Devient facultatif","Se déplace"]'::jsonb, 0, 'C’est une interrogation indirecte : l’accent reste, les signes ¿ ? partent.', 6),
    ('81a1473b-5117-5a80-90fe-cc2e47a4c951'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, 'L’espagnol exige l’inversion du sujet dans toute question.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*¿Tú hablas español?* est parfaitement correct : l’intonation suffit.', 7),
    ('55bb8069-3db3-52d2-a309-e8a7271873ee'::uuid, 'fff24d22-f084-5836-a621-9e7f92424879'::uuid, 'Devant un nom, l’espagnol préfère…', 'mcq', '["Qué (¿Qué día es hoy?)","Cuál (¿Cuál día es hoy?)","Quién","Cuánto"]'::jsonb, 0, '*¿Cuál día?* est un calque du français à éviter.', 8),
    ('336766e3-8547-5dd4-9ac7-cfb3b87b6e39'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, 'Où se place « no » dans la phrase ?', 'mcq', '["Juste devant le verbe","À la fin de la phrase","Après le verbe","Devant le sujet"]'::jsonb, 0, 'Seuls les pronoms compléments peuvent s’intercaler : *No te lo digo.*', 1),
    ('d028dc65-42d4-52d5-9cfb-9b783d63e5fd'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, 'Comment traduire « je ne vois rien » ?', 'mcq', '["No veo nada","Veo nada","No veo","Nada veo no"]'::jsonb, 0, 'La double négation est obligatoire quand le mot négatif suit le verbe.', 2),
    ('55a4dbd5-8248-536a-abb0-abaf4fd0604f'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, '« Nadie viene » est incorrect : il manque le « no ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Quand le mot négatif précède le verbe, le *no* disparaît.', 3),
    ('7764e5e4-508a-599c-a50b-9e50c2916ba4'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, 'Que signifie « tampoco » ?', 'mcq', '["Non plus","Encore","Déjà","Jamais"]'::jsonb, 0, '*A mí tampoco me gusta* : à moi non plus.', 4),
    ('e7be982e-684d-545b-9b2d-0767ca7bf981'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, 'Comment dit-on « ne… plus » ?', 'mcq', '["Ya no","Todavía no","Nunca","Ni"]'::jsonb, 0, '*Ya no fumo* : je ne fume plus. *Todavía no* signifie « pas encore ».', 5),
    ('e215993e-7637-58c5-917d-5b641e3b1c82'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, 'Après une négation, pour rectifier, on emploie…', 'mcq', '["Sino","Pero","Porque","Aunque"]'::jsonb, 0, '*No es francés sino español.* *Pero* oppose sans rectifier.', 6),
    ('f24da7e0-f66a-5608-9461-5dc1a7276923'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, '« Ninguno » s’apocope en « ningún » devant un masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ningún libro*, mais *ninguna casa* et *ninguno de ellos*.', 7),
    ('0cef0ac3-6cc5-5b73-99c4-8c20506c03c0'::uuid, '2052cf7f-01f1-5998-8dbd-ea7595c95612'::uuid, 'Devant un verbe conjugué, « sino » devient…', 'mcq', '["Sino que","Sino de","Sino a","Sino el"]'::jsonb, 0, '*No canta sino que grita.*', 8),
    ('c576c42a-8506-5488-9a58-d85779f55d69'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, 'Quelle relative s’écrit entre virgules ?', 'mcq', '["L’explicative","La déterminative","Les deux","Aucune"]'::jsonb, 0, 'L’explicative ajoute une information supprimable.', 1),
    ('bba33f80-57c2-5933-8a50-0df5144be541'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, '« Busco una secretaria que hable inglés » emploie le subjonctif parce que…', 'mcq', '["L’antécédent est indéfini : elle reste à trouver","L’antécédent est connu","La relative est explicative","Le verbe est irrégulier"]'::jsonb, 0, 'Avec un antécédent réel, l’indicatif : *que habla inglés*.', 2),
    ('3acb81a4-90d7-573b-9616-feca7b51347a'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, 'La virgule d’une relative ne change pas le sens de la phrase.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Los alumnos que estudian* ne désigne pas les mêmes élèves que *los alumnos, que estudian*.', 3),
    ('a832f1ff-7692-53cb-8043-40c893202780'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo en","La casa vivo en que","La casa en vivo que"]'::jsonb, 0, 'La préposition précède toujours le relatif en espagnol.', 4),
    ('1f85327a-3ed4-5ffb-9d6d-4141eed4f8a2'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, 'Après « No conozco a nadie que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au gérondif"]'::jsonb, 0, 'La négation rend l’antécédent inexistant, donc indéfini.', 5),
    ('bbbd02b9-1d03-5613-bb34-239f51e72f55'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, 'Pour renvoyer à une idée entière, on emploie…', 'mcq', '["Lo que","El que","Quien","Cuyo"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 6),
    ('bce6f3c5-713a-56c0-a264-cecbf23e0a7f'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, 'Dans une relative déterminative, on emploie normalement « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Quien* est réservé aux explicatives et aux emplois avec préposition.', 7),
    ('b8627ada-57b7-59b7-bae4-0ab3fc49137b'::uuid, '629b92c9-baa2-5ac6-aa4d-8fe3cc29408c'::uuid, '« El que quiera, que venga » se traduit par…', 'mcq', '["Que celui qui veut vienne","Ce qu’il veut, qu’il vienne","Celui qu’il veut vient","Il veut qu’il vienne"]'::jsonb, 0, 'Relatif sans antécédent exprimé, suivi du subjonctif.', 8),
    ('dae458b4-a433-5ea3-8f36-b30dbc8f8781'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, 'Après « Quiero que… », le verbe est…', 'mcq', '["Au subjonctif","À l’indicatif","À l’infinitif","Au conditionnel"]'::jsonb, 0, 'La volonté commande le subjonctif : *Quiero que vengas.*', 1),
    ('c088d734-c008-53a4-89e8-1b58b7a75226'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, '« Creo que viene » et « No creo que venga » emploient le même mode.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Nier la certitude fait passer l’indicatif au subjonctif.', 2),
    ('61e2e5c9-316a-5925-b062-629ad6b0b919'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, 'Comment dit-on « je veux venir » (même sujet) ?', 'mcq', '["Quiero venir","Quiero que venga","Quiero que vengo","Quiero de venir"]'::jsonb, 0, 'Même sujet : infinitif, sans *que*.', 3),
    ('45f3e57d-53d4-55e6-88f8-c4386cf0869a'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, 'Après « Es necesario que… », on emploie…', 'mcq', '["Le subjonctif","L’indicatif","Le gérondif","Le participe"]'::jsonb, 0, 'Le jugement impersonnel commande le subjonctif : *que estudies*.', 4),
    ('59a3ab83-c446-57c8-8234-729677b22f8f'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, '« Ojalá » est toujours suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Ojalá llueva* : c’est l’expression du souhait par excellence.', 5),
    ('51226b14-b3ca-5705-8ddc-d4afe3a70142'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, 'Quand le verbe principal est au passé, le subjonctif présent devient…', 'mcq', '["L’imparfait du subjonctif","Le passé simple","Le conditionnel","Le futur"]'::jsonb, 0, '*Quería que vinieras* — les formes en -ra et en -se sont équivalentes.', 6),
    ('4be417c0-c92b-5a9a-9b5f-e145cfefd048'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, 'Après « Dudo que… », on emploie l’indicatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le doute appelle le subjonctif : *Dudo que sea verdad.*', 7),
    ('e3a4cfb9-0d70-50c5-b2f7-0443fa8205c3'::uuid, '5e29bbd0-8764-5b65-9c18-6bfae4db251b'::uuid, 'Le « que » de la complétive peut être supprimé en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il se maintient toujours : *Espero que me llames.*', 8),
    ('8e4b79dd-c326-5b00-ae20-5037b013aa46'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, 'Quel est le genre de « la sangre » ?', 'mcq', '["Féminin","Masculin","Neutre","Les deux"]'::jsonb, 0, 'Piège classique : le français dit « le sang ».', 1),
    ('983d5ff2-a2c9-51b1-843d-d5469bd58aa7'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, 'Les noms en « -ción » et « -dad » sont féminins.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La canción*, *la ciudad*, *la libertad*.', 2),
    ('3b1a7cd3-80e9-586d-9fac-1f3d66a6c960'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, 'Quel est le genre de « el problema » ?', 'mcq', '["Masculin, malgré le -a final","Féminin","Variable","Neutre"]'::jsonb, 0, 'Comme *el tema*, *el idioma*, *el sistema* : origine grecque.', 3),
    ('560ce2af-34e4-5c01-9f87-d69f3b927455'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, 'Quel est le pluriel de « lápiz » ?', 'mcq', '["Lápices","Lápizs","Lápizes","Lápiz"]'::jsonb, 0, 'Le -z devient -c devant -es.', 4),
    ('03fff97e-42df-5279-a7ce-fed3a9ac549d'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, '« El lunes » au pluriel devient « los lunes ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les mots en -s non accentués sur la dernière syllabe sont invariables.', 5),
    ('5ea05852-cbd7-5129-80fb-e88b89136182'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, 'Quel est le pluriel de « el examen » ?', 'mcq', '["Los exámenes","Los examenes","Los exámens","Los examen"]'::jsonb, 0, 'L’accent écrit apparaît pour conserver la même syllabe tonique.', 6),
    ('e5c32a2b-04ef-55b1-be5e-6720d3479467'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, '« El color » est masculin en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que le français hésite : la couleur est féminine.', 7),
    ('1c324a1f-d1ee-52a8-8bec-c83fb51f1da0'::uuid, '2e14fc11-e3b1-523a-b6bc-05bfc014703f'::uuid, 'Comment se forme le pluriel après une consonne ?', 'mcq', '["On ajoute -es","On ajoute -s","On ne change rien","On double la consonne"]'::jsonb, 0, '*Papel → papeles*, *ciudad → ciudades*.', 8),
    ('4c2cf3ce-6ffd-5c48-9a91-006469987de6'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, 'Quelles sont les deux contractions de l’espagnol ?', 'mcq', '["Al et del","Al, del et col","Del seulement","Al, del, pel"]'::jsonb, 0, '*a + el = al*, *de + el = del*.', 1),
    ('5361609b-0985-5a50-b8c8-f9c6b30ea098'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, 'Pourquoi dit-on « el agua » ?', 'mcq', '["Le nom féminin commence par un a- tonique","Le nom est masculin","C’est une exception isolée","L’article est neutre"]'::jsonb, 0, 'Le mot reste féminin : *el agua fría*, *las aguas*.', 2),
    ('075f91ba-7001-5e08-b7bc-74ce42501681'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, '« El agua » devient « los aguas » au pluriel.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le pluriel reprend l’article féminin : *las aguas*.', 3),
    ('1fe33598-479c-5a72-9d0d-8456dd89d2a2'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, 'Que précède l’article neutre « lo » ?', 'mcq', '["Un adjectif, un adverbe ou un relatif","Un nom masculin","Un nom féminin","Un verbe"]'::jsonb, 0, '*Lo importante*, *lo mejor*, *lo que dices*.', 4),
    ('3c42eb1b-c2b8-5b39-9153-4440f5bebadb'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, 'Comment dit-on « je suis professeur » ?', 'mcq', '["Soy profesor","Soy un profesor","Estoy profesor","Soy el profesor"]'::jsonb, 0, 'Pas d’article devant une profession attribut, sauf si elle est qualifiée.', 5),
    ('44287fe0-c887-54e0-a2a3-98a1eb5f55be'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, '« Unos amigos » signifie « quelques amis ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pluriel de l’indéfini exprime l’approximation.', 6),
    ('15cdb8c2-8cf0-5e1c-84cb-1f76f7bce670'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, 'Comment traduire « un autre jour » ?', 'mcq', '["Otro día","Un otro día","El otro día","Uno otro día"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 7),
    ('1b53c241-51f2-5ccd-8776-3a1bb1ab10c3'::uuid, 'a243f957-4397-512b-bad4-b002886bc787'::uuid, '« La avenida » ne prend pas « el » parce que…', 'mcq', '["L’accent tonique ne tombe pas sur le a initial","Le mot est masculin","Le mot est pluriel","Le mot est étranger"]'::jsonb, 0, 'La règle ne vaut que pour un a- ou ha- TONIQUE.', 8),
    ('bbdff9e7-7168-5473-af6e-49d1b5d2bd23'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, 'Combien l’espagnol a-t-il de séries de démonstratifs ?', 'mcq', '["Trois : este, ese, aquel","Deux : este et ese","Une seule","Quatre"]'::jsonb, 0, 'Elles correspondent à *aquí*, *ahí*, *allí*.', 1),
    ('53df8df1-c1fb-58ae-9c4d-5cc223d016d6'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, 'Quel démonstratif désigne ce qui est près de l’interlocuteur ?', 'mcq', '["Ese","Este","Aquel","Esto"]'::jsonb, 0, '*Ese libro que tienes en la mano.*', 2),
    ('f32a635a-16a4-56b7-9af4-d1bf6c4d82e0'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, 'Les démonstratifs neutres « esto, eso, aquello » sont invariables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et ils ne sont jamais suivis d’un nom.', 3),
    ('546ed18b-51c9-54d2-bc4a-722e9e7dfcfd'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, 'Comment reprendre une phrase entière ?', 'mcq', '["Par un neutre : eso","Par ese","Par esta","Par aquellos"]'::jsonb, 0, '*No vino, y eso me molestó.*', 4),
    ('314d4b82-e772-5db1-914b-6df9af808d34'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, 'Depuis 2010, le pronom démonstratif porte un accent écrit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La RAE l’a supprimé : on écrit *este* pronom comme *este* adjectif.', 5),
    ('7bc960e6-c328-5c0a-8b12-18da63fdef5b'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, '« Aquellos tiempos » évoque…', 'mcq', '["Une époque lointaine","L’instant présent","Le futur proche","La semaine dernière"]'::jsonb, 0, '*Aquel* marque la plus grande distance, y compris temporelle.', 6),
    ('992f3857-f6aa-5502-8f42-b4270c2e9188'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, 'Comment traduire « qu’est-ce que c’est ? » ?', 'mcq', '["¿Qué es esto?","¿Qué es este?","¿Qué es ésta?","¿Qué es aquel?"]'::jsonb, 0, 'La chose n’étant pas identifiée, on emploie le neutre.', 7),
    ('aeddf0e2-a280-50e5-a82d-d24c42cb1d07'::uuid, '42f810a3-209a-5929-bf32-fc46eede9ac0'::uuid, '« Esta » et « estas » sont les formes féminines de « este ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin : *este / estos* ; féminin : *esta / estas*.', 8),
    ('acad8e27-5f6d-5cd8-b9ea-977e334ba006'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, 'Où se place l’adjectif espagnol par défaut ?', 'mcq', '["Après le nom","Avant le nom","En fin de phrase","Avant le verbe"]'::jsonb, 0, 'C’est la position qui classe objectivement : *un coche rojo*.', 1),
    ('e819ad1f-26cd-5e34-8f44-c03a607fc15f'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, '« Un gran hombre » et « un hombre grande » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier est un grand homme, le second un homme de grande taille.', 2),
    ('f156d63a-feee-5423-8fca-67d509a8d135'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, 'Quel adjectif a quatre formes ?', 'mcq', '["Alto (alto, alta, altos, altas)","Inteligente","Fácil","Verde"]'::jsonb, 0, 'Les adjectifs en -e ou en consonne sont invariables en genre.', 3),
    ('222fd5cd-cf22-5faf-82c2-111563789b71'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, '« Un chico y una chica simpáticos » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec des noms de genres différents, l’adjectif se met au masculin pluriel.', 4),
    ('8dd59cef-4d73-58be-bcca-76f9aa2cc019'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, 'Que signifie « un pobre hombre » ?', 'mcq', '["Un homme à plaindre","Un homme sans argent","Un homme humble","Un homme malade"]'::jsonb, 0, 'Placé après, *un hombre pobre* désigne la pauvreté matérielle.', 5),
    ('ed880263-5fa0-5b9e-8f03-b1b53625563a'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, 'Les adjectifs de nationalité forment un féminin.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Español/española*, *inglés/inglesa*, même s’ils finissent par une consonne.', 6),
    ('8591d959-c437-55f1-b09c-b6581e270004'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, '« Un viejo amigo » signifie…', 'mcq', '["Un ami de longue date","Un ami âgé","Un ancien ami fâché","Un ami d’enfance uniquement"]'::jsonb, 0, 'La place avant le nom porte l’appréciation, pas l’âge.', 7),
    ('1cbaec36-3c1b-5745-9e88-f4959419e210'::uuid, 'c39317cd-9ee0-5d2d-a60e-bb7d88d63feb'::uuid, 'Un adjectif placé avant le nom exprime souvent une appréciation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*La blanca nieve*, *un buen amigo* : le regard de celui qui parle.', 8),
    ('5abf2906-9765-5f50-a95d-4b1403a61238'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, 'Pourquoi l’espagnol omet-il souvent le pronom sujet ?', 'mcq', '["La terminaison du verbe identifie déjà la personne","C’est un usage familier","Pour aller plus vite","Le pronom n’existe pas"]'::jsonb, 0, 'On l’exprime pour insister, opposer ou lever une ambiguïté.', 1),
    ('c091a18b-f0fe-5ade-bbbe-e875054aec38'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, '« Usted » se conjugue à la deuxième personne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'À la troisième : *¿Usted habla español?* — il vient de *vuestra merced*.', 2),
    ('a4a62e99-7efb-5c3a-a26d-8bbf5fb9ea6b'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, 'Quel pronom remplace « vosotros » en Amérique latine ?', 'mcq', '["Ustedes","Vos","Tú","Nosotros"]'::jsonb, 0, '*Vosotros* n’y est pas employé, même entre amis.', 3),
    ('f3555332-3573-5c18-9654-ffe3b8a1933a'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, 'Le « voseo » consiste à employer…', 'mcq', '["Vos à la place de tú","Usted à la place de tú","Vosotros à la place d’ustedes","Nos à la place de nosotros"]'::jsonb, 0, '*Vos tenés*, *vos sos* : norme d’Argentine, d’Uruguay, du Paraguay.', 4),
    ('b8408015-ce28-5463-a61f-e6311c2a6d7b'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, 'Comment traduire « pour moi » ?', 'mcq', '["Para mí","Para yo","Por yo","Para me"]'::jsonb, 0, 'Après préposition, *yo* devient *mí* et *tú* devient *ti*.', 5),
    ('8cf4adf3-2d0e-5686-acf2-e7a05266cc7e'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, '« Conmigo » et « contigo » sont des formes soudées irrégulières.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne dit jamais « con mí » ni « con ti ».', 6),
    ('06aa289a-32c5-55e8-8dfe-2a8dd8a9e0b2'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, 'Après « entre » et « según », quel pronom emploie-t-on ?', 'mcq', '["Tú et yo","Ti et mí","Te et me","Usted seulement"]'::jsonb, 0, '*Entre tú y yo*, *según tú* : ces prépositions font exception.', 7),
    ('74907370-6e94-5fc2-801f-06b8ccdf0a51'::uuid, '491647db-e489-5b99-a67c-510d61ff220f'::uuid, '« Yo no lo he dicho » exprime une insistance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sans le *yo*, la phrase serait neutre : le pronom souligne le contraste.', 8),
    ('8f4c85dd-22a5-5ca6-87f0-e71ee6b83952'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, 'Dans quel ordre se placent les pronoms compléments ?', 'mcq', '["COI puis COD","COD puis COI","Selon la longueur du mot","Indifféremment"]'::jsonb, 0, '*Me lo da*, *te la doy* : le COI passe toujours devant.', 1),
    ('6822d50f-5d8c-5178-8f18-5d68abdf2a81'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, 'Que devient « le » devant « lo » ?', 'mcq', '["Se","Lo","La","Les"]'::jsonb, 0, '*Se lo doy* : « le lo doy » n’existe pas.', 2),
    ('b05a4e2c-f453-54c3-8b15-ed1f093b50ef'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, 'Avec un impératif affirmatif, le pronom se soude derrière le verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dámelo*, *dímelo* — et l’accent écrit apparaît.', 3),
    ('5404057f-31ba-586d-843b-9bc5ad3989e8'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, 'Où se place le pronom avec un impératif négatif ?', 'mcq', '["Devant le verbe","Soudé derrière","Après le sujet","En fin de phrase"]'::jsonb, 0, '*No me lo des* : l’enclise ne vaut que pour l’affirmatif.', 4),
    ('f1be09a3-a2ad-51ea-a665-7cd2763485ac'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, '« Voy a decírtelo » et « Te lo voy a decir » sont tous deux corrects.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec un verbe conjugué + infinitif, les deux placements sont admis.', 5),
    ('615351a7-e9fa-555f-9cf1-bc5055bd7bb1'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, 'Quel pronom COD correspond à « la » (féminin) ?', 'mcq', '["La","Le","Se","Ella"]'::jsonb, 0, '*La veo* : je la vois. *Le hablo* serait un COI.', 6),
    ('df9b9b28-f985-522c-a084-d9053ce3998b'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, 'Le redoublement du COI est une lourdeur à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : *Le doy el libro a Juan*, *A mí me gusta*.', 7),
    ('733c12b6-2c7d-5471-9785-f58f4cf40030'::uuid, 'ebf63a11-b192-5d3d-a38e-ce9f28284c24'::uuid, 'L’accent écrit sur « dámelo » sert à…', 'mcq', '["Conserver la syllabe tonique du verbe d’origine","Marquer l’impératif","Distinguer le COD du COI","Signaler un pluriel"]'::jsonb, 0, 'L’enclise allonge le mot : sans accent, la prononciation changerait.', 8),
    ('817b268b-3b4b-5c2e-955f-a9f9022328b5'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, 'Avec quoi le possessif espagnol s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Avec l’article"]'::jsonb, 0, '*Mis libros* : le -s vient des livres, pas de moi.', 1),
    ('8e864dbb-6424-5002-8cf6-7ccd844a86a0'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, 'Comment traduire « je me lave les mains » ?', 'mcq', '["Me lavo las manos","Me lavo mis manos","Lavo mis manos","Me lavo mías manos"]'::jsonb, 0, 'Corps et vêtements prennent l’article défini, pas le possessif.', 2),
    ('f877092c-7049-578d-bdfa-df82f36d34df'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, '« Su » peut signifier son, sa, leur ou votre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où le recours à *de él*, *de usted* pour lever l’ambiguïté.', 3),
    ('91b91663-7abb-51d4-814e-53eef82a6153'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, 'Comment dit-on « un ami à moi » ?', 'mcq', '["Un amigo mío","Un mi amigo","Un amigo de mí","Mi un amigo"]'::jsonb, 0, 'La forme tonique se place après le nom.', 4),
    ('6e6ebca3-59f5-5252-91fa-f9f54c2e82dd'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, 'Quelles formes atones varient en genre ?', 'mcq', '["Nuestro et vuestro","Mi et tu","Su seulement","Toutes"]'::jsonb, 0, '*Nuestra casa*, *vuestros libros* — mais *mi* et *tu* restent invariables.', 5),
    ('b4188beb-f498-5a5b-9e73-f35e61b59f19'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, '« El mío » est un pronom possessif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Article + forme tonique : *El mío es más grande.*', 6),
    ('517853a1-a65e-5243-8076-b15e0940fc96'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, 'Comment traduire « il a mal à la tête » ?', 'mcq', '["Le duele la cabeza","Le duele su cabeza","Duele su cabeza","Tiene mal su cabeza"]'::jsonb, 0, 'Le pronom *le* porte déjà l’information de possession.', 7),
    ('3c619cd5-b498-5239-9593-db5c0ff36ff7'::uuid, 'b7b55d0f-f052-5e83-95a7-93dbe286d0e7'::uuid, 'Au vocatif, on dit « ¡Hijo mío! ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La forme tonique suit le nom en apostrophe : *¡Madre mía!*', 8),
    ('fdfb73ef-5980-5f83-99ae-deeddeef2ac8'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, 'Avec quoi « cuyo » s’accorde-t-il ?', 'mcq', '["Avec ce qui est possédé","Avec le possesseur","Avec le verbe","Il est invariable"]'::jsonb, 0, '*El escritor cuya novela leí* : *cuya* s’accorde avec *novela*.', 1),
    ('ab36f173-6017-56b7-9cf9-d931a1674327'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, '« Cuyo » peut être suivi d’un article.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Cuyo el libro » n’existe pas : *cuyo libro* directement.', 2),
    ('e499fc2e-b8e3-56db-9bdb-4aef37d59d76'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, 'Quel relatif s’emploie uniquement pour des personnes ?', 'mcq', '["Quien","Que","Cuyo","Donde"]'::jsonb, 0, '*La persona con quien hablo.*', 3),
    ('65532ad6-c9a6-5686-9b68-1e7d3d5b405f'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, 'Comment traduire « la maison dans laquelle je vis » ?', 'mcq', '["La casa en la que vivo","La casa que vivo","La casa cuya vivo","La casa quien vivo"]'::jsonb, 0, 'Après préposition, *que* prend l’article.', 4),
    ('a80a3688-2717-5354-9eef-66f11d1379e1'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, 'Pour reprendre une idée entière, on emploie « lo que » ou « lo cual ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Llegó tarde, lo que me molestó.*', 5),
    ('93fec7bb-756f-5448-bfc3-4cf6a46e3d3d'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, '« Los que quieran, que vengan » signifie…', 'mcq', '["Que ceux qui veulent viennent","Ceux-là veulent venir","Ils veulent qu’ils viennent","Que veulent-ils venir"]'::jsonb, 0, '*El que / los que* sans antécédent = celui qui / ceux qui.', 6),
    ('3d768bbe-2c84-5685-b31d-e41bae040c5b'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, 'Comment demander « à qui est-ce ? »', 'mcq', '["¿De quién es?","¿Cuyo es?","¿Que es de?","¿Quien es de?"]'::jsonb, 0, '*Cuyo* ne s’emploie jamais dans une question.', 7),
    ('87804788-651e-5f5e-bc59-afc05fba858b'::uuid, '59d67897-9972-5e0c-87bb-5cca5b137f07'::uuid, '« El cual » appartient à un registre plus soutenu que « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Surtout après une préposition longue : *la razón por la cual*.', 8),
    ('3bf4d2b8-26e4-5358-9b5d-3c7ee1252db9'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, 'Comment traduire « je ne vois personne » ?', 'mcq', '["No veo a nadie","No veo nadie","Veo a nadie","No veo alguien"]'::jsonb, 0, 'Double négation, et le *a* devant un COD de personne.', 1),
    ('ada51282-1730-57d9-831a-341cc0865e5c'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, '« Cualquiera » s’apocope en « cualquier » devant un nom.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Masculin comme féminin : *cualquier día*, *cualquier mujer*.', 2),
    ('19bed4ac-fc80-5258-bae2-a71baaae5593'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, '« Cada » peut-il se mettre au pluriel ?', 'mcq', '["Non, il est invariable","Oui : cadas","Oui au féminin seulement","Oui devant un nombre"]'::jsonb, 0, '*Cada día*, *cada dos horas* ; « chacun » se dit *cada uno*.', 3),
    ('0a94b68a-ee1c-5897-8685-1ad67dc53e00'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, 'Placé après le nom, « alguno » prend un sens…', 'mcq', '["Négatif renforcé","Positif renforcé","Interrogatif","Neutre"]'::jsonb, 0, '*No tengo duda alguna* = aucun doute.', 4),
    ('57ae4eb5-c57d-5b29-80ca-d6a1afac3ade'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, '« Todos días » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Todo* exige l’article : *todos los días*.', 5),
    ('6f0b3808-c437-5344-b027-291bb6772e56'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, 'Que signifie « los demás » ?', 'mcq', '["Les autres, le reste","Les mêmes","Trop nombreux","Chacun"]'::jsonb, 0, '*Los demás alumnos se fueron.*', 6),
    ('fd8e07f8-642e-55fb-bb83-c7207553a10a'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, '« Alguien » et « nadie » sont invariables et toujours singuliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils ne s’accordent ni en genre ni en nombre.', 7),
    ('07348bbf-3f60-55a3-98bb-6fb8d3aa41b9'::uuid, 'c9a36227-d0ef-562f-8807-c70ce17fd412'::uuid, 'Comment dit-on « un autre livre » ?', 'mcq', '["Otro libro","Un otro libro","El otro libro","Otro el libro"]'::jsonb, 0, '*Otro* ne prend jamais l’article indéfini.', 8),
    ('cbe55f1f-a6ba-59d8-9aff-d62f50fb940f'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, 'Comment traduire « aussi grand que toi » ?', 'mcq', '["Tan alto como tú","Tanto alto como tú","Más alto como tú","Tan alto que tú"]'::jsonb, 0, '*Tan* devant un adjectif, *como* comme second terme.', 1),
    ('62aedcc8-4091-5272-b410-7a3d21bc9ba1'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, 'Comment traduire « autant de livres que toi » ?', 'mcq', '["Tantos libros como tú","Tan libros como tú","Tanto libros como tú","Más libros como tú"]'::jsonb, 0, '*Tanto* devant un nom, et il s’accorde : *tantos libros*.', 2),
    ('00d9a1ce-bc83-5cb5-b78f-0c0f941f354a'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, 'Devant un nombre, on emploie « de » et non « que ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Más de veinte libros*, *menos de diez euros*.', 3),
    ('4432df94-d93c-5f39-bf29-71875eec4bf4'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, 'Que signifie « No tengo más que diez euros » ?', 'mcq', '["Je n’ai que dix euros","Je n’ai pas plus de dix euros","J’ai plus de dix euros","J’ai environ dix euros"]'::jsonb, 0, 'En phrase négative, *más que* signifie « seulement ».', 4),
    ('d60a8b11-cb37-56d5-aa5c-299b1130f25e'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, '« Más mejor » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les comparatifs irréguliers ne se combinent jamais avec *más*.', 5),
    ('b3ca04d0-0a22-5746-8deb-18296e92e53a'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, 'Quel est le comparatif de « malo » ?', 'mcq', '["Peor","Más malo","Menor","Mal"]'::jsonb, 0, 'Comme *bueno → mejor*, *grande → mayor*, *pequeño → menor*.', 6),
    ('7934730f-ed14-554a-9066-4e181f7df954'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, 'Comment traduire « plus difficile qu’il n’y paraît » ?', 'mcq', '["Más difícil de lo que parece","Más difícil que parece","Más difícil como parece","Tan difícil que parece"]'::jsonb, 0, 'Quand le second terme est une proposition : *de lo que*.', 7),
    ('75f8034c-0077-563b-8670-c62e2e0fd80a'::uuid, '6c89e76b-75c2-50c2-8fd0-9860a1d36830'::uuid, '« Trabaja tanto como yo » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un verbe, on emploie *tanto como*, invariable.', 8),
    ('501c8860-de21-5173-b10f-bb7b70a077ec'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, 'Comment traduire « le plus grand du monde » ?', 'mcq', '["El más grande del mundo","El más grande en el mundo","El mucho grande del mundo","El más grande que el mundo"]'::jsonb, 0, 'Le complément du superlatif relatif se construit avec *de*.', 1),
    ('6ca5cf84-96a3-5c58-8f39-878167a70a9c'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, '« Muy guapísimo » est une tournure correcte.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On emploie *muy* OU le suffixe -ísimo, jamais les deux.', 2),
    ('c6104a76-4fe1-57e9-9665-40e3ff806367'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, 'Quel est le superlatif absolu de « rico » ?', 'mcq', '["Riquísimo","Ricísimo","Rikísimo","Ricoísimo"]'::jsonb, 0, 'Le c devient qu pour conserver le son [k].', 3),
    ('d2345688-c1f7-5b69-ab9c-7fe2ec648fdf'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, 'Quel est le superlatif absolu de « feliz » ?', 'mcq', '["Felicísimo","Felizísimo","Felisísimo","Felizmo"]'::jsonb, 0, 'Le z devient c devant le i.', 4),
    ('d80f5319-55a9-54a6-bbab-46d546e2bcd3'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, '« Óptimo » est le superlatif savant de « bueno ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Comme *pésimo* pour *malo*, *máximo* pour *grande*.', 5),
    ('8e6cbf8a-aed2-5d91-b34b-fbd44c27c653'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, 'Que devient le « g » de « largo » au superlatif ?', 'mcq', '["Il devient gu : larguísimo","Il disparaît","Il devient j","Il double"]'::jsonb, 0, 'Pour conserver le son [g] devant le i.', 6),
    ('c15c9e2d-3e83-545a-bf7f-d64c09ac7855'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, 'Le superlatif relatif compare à l’intérieur d’un ensemble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El alumno más inteligente de la clase* : l’ensemble est la classe.', 7),
    ('63f0b05d-e176-5159-8847-2f66bd1dfded'::uuid, '95c95cc3-6006-5d97-8356-e0095c560e08'::uuid, 'Comment dit-on « énormément » avec un suffixe ?', 'mcq', '["Muchísimo","Muy mucho","Mucho muy","Máximo"]'::jsonb, 0, '*Mucho* prend lui aussi le suffixe -ísimo.', 8),
    ('fce36499-f682-5dca-8d74-ff60073f67ab'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, 'Quelle est la forme apocopée de « bueno » devant un nom masculin ?', 'mcq', '["Buen","Bue","Buenó","Bon"]'::jsonb, 0, '*Un buen amigo*, mais *un amigo bueno* garde la forme pleine.', 1),
    ('c9e58887-2d60-5bf7-9e1e-1178f36928a7'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, '« Grande » s’apocope devant un nom féminin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Una gran mujer* : c’est le seul adjectif à s’apocoper aux deux genres.', 2),
    ('67c6e73c-58b1-5813-beb3-b0a30bfbf9b2'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, 'Comment dit-on « cent euros » ?', 'mcq', '["Cien euros","Ciento euros","Cientos euros","Cien de euros"]'::jsonb, 0, '*Ciento* s’apocope devant un nom, et devant *mil* et *millones*.', 3),
    ('0fd404ef-124c-5ba1-b421-31dbcd15cdd6'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, 'Quelle est la forme correcte : « santo Domingo » ou « Santo Domingo » ?', 'mcq', '["Santo Domingo : pas d’apocope devant To- et Do-","San Domingo","Sant Domingo","Sa Domingo"]'::jsonb, 0, 'Même exception pour *Santo Tomás* et *Santo Tomé*.', 4),
    ('7fda4b7d-90d2-5210-9d2e-143fdafa7b9e'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, '« Tercero » devient « tercer » devant un nom masculin singulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*El tercer año*, comme *el primer piso*.', 5),
    ('9d1b37df-fe58-5a7d-9b3a-852f7c7b3197'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, 'Quelle est la forme apocopée de « cualquiera » ?', 'mcq', '["Cualquier, aux deux genres","Cualqui","Cualquiero","Il ne s’apocope pas"]'::jsonb, 0, '*Cualquier día*, *cualquier mujer*.', 6),
    ('38f61ce1-0c23-5668-a43c-ad353fce1d39'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, '« Recién » s’emploie devant un participe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Recién nacido*, *recién llegado*, *recién casados*.', 7),
    ('57c62962-5bdc-59e3-b3de-3b52c513994f'::uuid, '34e48d98-1e6c-5b35-8e20-a14aed85defa'::uuid, '« Ciento veinte » garde la forme pleine parce que…', 'mcq', '["Ciento est suivi d’un autre nombre","Ciento est féminin","Le nombre est pair","Il s’agit d’un pluriel"]'::jsonb, 0, 'L’apocope ne joue que devant un nom, *mil* ou *millones*.', 8),
    ('66a6cbc7-6c64-5f88-95d8-282bf237e8a1'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, 'Combien l’espagnol a-t-il d’auxiliaires de temps composés ?', 'mcq', '["Un seul : haber","Deux : haber et ser","Deux : haber et tener","Trois"]'::jsonb, 0, 'Contrairement au français, aucune hésitation entre « être » et « avoir ».', 1),
    ('ce895356-4fa7-5283-aea0-5365cf6fe215'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, 'Le participe passé s’accorde avec « haber ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Jamais : *la carta que he escrito*, *ellas han venido*.', 2),
    ('9a283dba-b5bd-5723-81a8-2422a9c2685c'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, 'Comment traduire « il y a deux livres » ?', 'mcq', '["Hay dos libros","Han dos libros","Hays dos libros","Están dos libros"]'::jsonb, 0, '*Hay* est invariable, même devant un pluriel.', 3),
    ('b3452079-1072-514a-9950-8bbcb1b28d2a'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, 'Peut-on placer un adverbe entre l’auxiliaire et le participe ?', 'mcq', '["Non, le bloc est soudé","Oui, toujours","Oui, si c’est une négation","Oui, à l’écrit seulement"]'::jsonb, 0, '*No lo he visto nunca*, jamais « he nunca visto ».', 4),
    ('43c59c48-78c6-5441-ac18-75ba63dbcfa5'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, '« Había » est la forme passée de « hay ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et elle reste au singulier : *Había muchos alumnos.*', 5),
    ('e2e76a33-593c-5c4c-99b1-433b36efaed1'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, 'Que signifie « Hay que estudiar » ?', 'mcq', '["Il faut étudier","J’ai étudié","Il y a des études","Il faut que j’étudie"]'::jsonb, 0, 'Obligation impersonnelle, sans sujet exprimé.', 6),
    ('6f42a270-54df-5dfd-b832-1483a0e334b4'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, 'Comment forme-t-on le plus-que-parfait ?', 'mcq', '["Había + participe passé","Hubo + participe passé","Era + participe passé","Estaba + participe passé"]'::jsonb, 0, '*Había salido cuando llegué.*', 7),
    ('1d2d14ad-927f-5612-a885-98fc30c966f0'::uuid, 'a4c92ceb-1629-51e0-9f66-b55b514f0e63'::uuid, '« Hay un banco en la plaza » et « El banco está en la plaza » disent la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '*Hay* pose l’existence, *estar* localise une chose déjà connue.', 8),
    ('b92b518d-5346-5b60-ba88-5eb6752f1941'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, 'Où se place le pronom réfléchi avec un infinitif ?', 'mcq', '["Soudé derrière : levantarse","Devant l’infinitif","En fin de phrase","Devant le sujet"]'::jsonb, 0, 'Même chose au gérondif et à l’impératif affirmatif.', 1),
    ('4375408c-6a5a-5183-87c0-7290a785e4ce'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, 'Dans « Se venden pisos », le verbe s’accorde avec « pisos ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un *se* passif : le sujet grammatical est *pisos*.', 2),
    ('f9a59863-5091-5417-9ac5-937360b3d171'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, 'Que signifie « Me voy » ?', 'mcq', '["Je m’en vais","Je vais bien","Je me vois","Je viens"]'::jsonb, 0, '*Ir* signifie aller, *irse* partir : le pronom change le sens.', 3),
    ('693c132b-918c-5416-9826-3e6a7fd8ac6f'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, 'Dans un « se » impersonnel, le verbe est…', 'mcq', '["Toujours au singulier","Toujours au pluriel","Accordé au complément","À l’infinitif"]'::jsonb, 0, '*Se dice que…*, *Aquí se come bien.*', 4),
    ('4cb7545b-3ccc-5046-b9ec-1aa8031eeb2a'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, '« Quejarse » et « atreverse » sont des verbes essentiellement pronominaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le pronom fait partie du verbe : il n’a pas de valeur réfléchie.', 5),
    ('ab36247c-6907-51a0-887b-86387415e33b'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, 'Que signifie « Se escriben » ?', 'mcq', '["Ils s’écrivent l’un à l’autre","Ils s’écrivent eux-mêmes","On les écrit","Ils sont écrits"]'::jsonb, 0, 'Valeur réciproque : plusieurs sujets agissent l’un sur l’autre.', 6),
    ('ffa99b33-f8f0-50a8-a2d4-8add18e2756c'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, '« Dormirse » signifie « s’endormir ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Alors que *dormir* signifie simplement dormir.', 7),
    ('3461b8c2-0496-59cf-ad26-b0bf13881cfa'::uuid, '175dadaf-942c-5c13-a1a3-d807129fa9f2'::uuid, 'Dans « Se comió toda la tarta », le pronom exprime…', 'mcq', '["Une nuance d’appropriation","Une réciprocité","Une passive","Une obligation"]'::jsonb, 0, 'Le pronominal d’intensité, sans valeur réfléchie.', 8),
    ('fba0eb69-1876-584e-a506-79025561ad56'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, 'Qu’est-ce qui déclenche la diphtongue ?', 'mcq', '["L’accent tonique sur la voyelle du radical","La terminaison en -ar","Le pluriel","La négation"]'::jsonb, 0, 'Quand l’accent passe sur la terminaison, la voyelle redevient simple.', 1),
    ('fac93704-e280-523a-b865-795e93779de6'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, 'Quelles personnes ne diphtonguent jamais ?', 'mcq', '["Nosotros et vosotros","Yo et tú","Él et ellos","Tú et vosotros"]'::jsonb, 0, 'Elles portent l’accent sur la terminaison : d’où la conjugaison « en botte ».', 2),
    ('fadece56-4336-52e5-883b-077e41babe6e'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, 'Quelle est la première personne de « poder » au présent ?', 'mcq', '["Puedo","Podo","Puedo/podo","Puedes"]'::jsonb, 0, 'La diphtongue o → ue apparaît sous l’accent.', 3),
    ('d450c692-0f11-54be-85a3-831cb91e5b36'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, '« Jugar » est le seul verbe à diphtonguer u → ue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Juego, juegas, juega… jugamos, jugáis, juegan.*', 4),
    ('f7e6d6f1-276b-51cb-8bc0-992768cd4c96'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, 'La diphtongue apparaît aussi au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seulement au présent de l’indicatif, au subjonctif présent et à l’impératif.', 5),
    ('feddc3ef-7437-5cb6-bc5d-c99a8d40c687'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, 'Quelle est la forme de « pensar » à la première personne du pluriel ?', 'mcq', '["Pensamos","Piensamos","Pensemos","Piensemos"]'::jsonb, 0, 'L’accent tombe sur la terminaison : pas de diphtongue.', 6),
    ('15fcec23-7707-5478-abf4-e3889f342918'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, 'Que devient « oler » quand il diphtongue ?', 'mcq', '["Huelo, avec un h","Uelo","Ólo","Oigo"]'::jsonb, 0, 'Un h purement orthographique s’ajoute devant le ue initial.', 7),
    ('5017e268-91ee-549e-9636-6efbfbe7c36b'::uuid, '12211257-831b-5096-b23f-f3de25eccaf3'::uuid, '« Pedir → pido » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un verbe à affaiblissement : le e devient i, il ne diphtongue pas.', 8),
    ('c2a70699-3078-5831-a7eb-32fdd4eb6d81'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, 'À quel groupe appartiennent tous les verbes à affaiblissement ?', 'mcq', '["Aux verbes en -ir","Aux verbes en -ar","Aux verbes en -er","À tous les groupes"]'::jsonb, 0, '*Pedir, servir, repetir, seguir…* — aucun -ar ni -er.', 1),
    ('83ee6dc1-9ce4-5458-8201-47672904d39b'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, 'Quelle est la troisième personne du passé simple de « pedir » ?', 'mcq', '["Pidió","Pedió","Pidó","Pediró"]'::jsonb, 0, 'Dès que la terminaison contient un ió ou un ie, le e s’affaiblit.', 2),
    ('20cdb8f4-0ecf-54ef-b618-8494ed6f298d'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, 'Au subjonctif présent, l’affaiblissement touche toutes les personnes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pida, pidas, pida, pidamos, pidáis, pidan* — y compris nosotros et vosotros.', 3),
    ('f56606d1-9507-5626-a797-711f0cc26c6c'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, 'Quel est le gérondif de « decir » ?', 'mcq', '["Diciendo","Deciendo","Diciento","Dicendo"]'::jsonb, 0, 'Le gérondif des verbes en -ir irréguliers porte l’affaiblissement.', 4),
    ('6ee68d84-b678-502e-8b13-57452eca165a'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, '« Dormir » est un verbe mixte : diphtongue au présent, affaiblissement ailleurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Duermo* au présent, mais *durmió* et *durmiendo*.', 5),
    ('a2398988-02e6-5d23-8bdf-c62b555761c4'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, 'Quelle est la première personne du présent de « seguir » ?', 'mcq', '["Sigo","Siguo","Sego","Seguo"]'::jsonb, 0, 'Le u disparaît devant o et a, sinon il se prononcerait.', 6),
    ('32762fe6-5e5d-5e3a-8b2d-d5c060885dba'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, 'Que devient le « g » de « elegir » devant un o ?', 'mcq', '["Il devient j : elijo","Il devient gu","Il disparaît","Il double"]'::jsonb, 0, 'Pour conserver le son [x] : *elijo*, *corrijo*.', 7),
    ('3f0a1e61-2173-5754-b320-1b1f6ba24b53'::uuid, '1d292d6e-fdc8-5d63-b8d8-bbbb5f43dc83'::uuid, '« Pedimos » porte l’affaiblissement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Comme *pedís*, il garde le e : l’accent tombe sur la terminaison.', 8),
    ('65ab4dc3-cca4-550b-8aa9-fe3690e596ac'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, 'Quel verbe employer pour la localisation d’une chose ?', 'mcq', '["Estar","Ser","Haber","Tener"]'::jsonb, 0, '*Madrid está en España* — mais un événement se situe avec *ser*.', 1),
    ('566e3aca-da49-59ae-92c7-1045aa5eeea0'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, '« Ser listo » et « estar listo » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '« Être malin » contre « être prêt » : deux mots différents.', 2),
    ('d1d68ef8-5f46-51b7-ba46-3f2a70ae7f91'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, 'Comment dit-on l’heure en espagnol ?', 'mcq', '["Son las tres","Están las tres","Hay las tres","Tienen las tres"]'::jsonb, 0, 'Heure, date, prix : toujours *ser*.', 3),
    ('509cf6b7-f8d9-505a-938f-ba56b80036cc'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, 'Que signifie « estar malo » ?', 'mcq', '["Être malade","Être méchant","Être mauvais","Être en colère"]'::jsonb, 0, '*Ser malo* signifie être méchant.', 4),
    ('d5e560ab-86fb-5245-98b9-9dc270b954c7'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, '« La fiesta es en mi casa » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un événement se situe avec *ser*, à la différence d’un lieu ou d’un objet.', 5),
    ('829f6753-36bd-5c56-ab2e-861ce44f8349'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, 'Quel verbe entre dans la forme progressive ?', 'mcq', '["Estar (estoy estudiando)","Ser","Haber","Ir"]'::jsonb, 0, '*Estar* + gérondif exprime l’action en cours.', 6),
    ('f078c309-5240-51f4-b1d3-f01cff17c9c0'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, '« La sopa está fría » décrit un état constaté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La soupe a refroidi ; *el hielo es frío* énonce une propriété.', 7),
    ('97c2c082-f7e5-5626-b032-07c3cd58acfe'::uuid, '6ba9e82d-6b5a-5ddb-850f-149c982347ad'::uuid, 'Comment dit-on « je suis d’accord » ?', 'mcq', '["Estoy de acuerdo","Soy de acuerdo","Tengo de acuerdo","Hay de acuerdo"]'::jsonb, 0, 'Expression figée avec *estar*, comme *estar de vacaciones*.', 8),
    ('1ac7ed28-eb7d-5b7f-9231-4ded8f1d3c48'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, 'Quelle est la terminaison du gérondif des verbes en -ar ?', 'mcq', '["-ando","-iendo","-yendo","-ado"]'::jsonb, 0, '*Hablar → hablando* ; les -er et -ir font *-iendo*.', 1),
    ('b49520bd-d194-58af-b8ac-6f2737c49c4b'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, 'Quel est le gérondif de « leer » ?', 'mcq', '["Leyendo","Leiendo","Leendo","Leído"]'::jsonb, 0, 'Le -iendo devient -yendo après une voyelle.', 2),
    ('2615e979-a5c6-5a6d-9002-6093b09f1f9a'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, '« Una caja conteniendo libros » est correct en espagnol.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le gérondif ne qualifie pas un nom : *una caja que contiene libros*.', 3),
    ('89c0ce40-c000-5bfd-867e-d0731aec652c'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, 'Que signifie « Llevo dos años estudiando español » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié deux ans","J’emporte deux ans d’espagnol","Je vais étudier deux ans"]'::jsonb, 0, '*Llevar* + durée + gérondif exprime la durée écoulée.', 4),
    ('67fcefab-9d81-50fa-b1ff-5f44abe9e2c0'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, 'Après une préposition, on emploie l’infinitif et non le gérondif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Antes de salir*, *sin decir nada*, *al entrar*.', 5),
    ('58203b95-243d-510c-8eb6-61e1b6aac7e5'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, 'Comment traduire « en entrant, j’ai vu Juan » ?', 'mcq', '["Al entrar, vi a Juan","Entrando, vi a Juan","En entrando, vi a Juan","Para entrar, vi a Juan"]'::jsonb, 0, '*Al* + infinitif exprime la simultanéité.', 6),
    ('7ba95d6c-ed2b-5140-ad9d-014b0569a0e6'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, '« Sigue lloviendo » signifie « il pleut toujours ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Seguir* + gérondif exprime la continuation.', 7),
    ('69030248-06fa-58c7-bf82-ea58bb4d4a6c'::uuid, 'c1b7564e-34d4-5919-b2e8-532409eef7bd'::uuid, 'Quel est le gérondif de « dormir » ?', 'mcq', '["Durmiendo","Dormiendo","Duermiendo","Durmendo"]'::jsonb, 0, 'L’affaiblissement o → u apparaît au gérondif des verbes en -ir.', 8),
    ('af532895-fb9e-5d78-8721-a045142ba48d'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, 'Le participe employé avec « haber » s’accorde-t-il ?', 'mcq', '["Jamais","Toujours","Seulement au féminin","Seulement au pluriel"]'::jsonb, 0, '*Ellas han llegado*, *las cartas que he escrito*.', 1),
    ('9606d741-b4f4-5bb3-bf27-4a5242460f14'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, 'Quel est le participe passé de « escribir » ?', 'mcq', '["Escrito","Escribido","Escribado","Escripto"]'::jsonb, 0, 'Comme *abrir → abierto*, *hacer → hecho*, *ver → visto*.', 2),
    ('9990e262-e63b-5ebb-9d7d-8284b3920d28'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, '« La puerta está cerrada » comporte un accord.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec *estar*, le participe s’accorde avec le sujet.', 3),
    ('d92fdd68-2747-5b9d-bb0e-8cd97ac1eb5e'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, 'Quelle différence entre « fue construida » et « está construida » ?', 'mcq', '["La première décrit l’action, la seconde l’état résultant","Aucune","La première est un futur","La seconde est un passé simple"]'::jsonb, 0, '*Ser* + participe = passive d’action ; *estar* + participe = état.', 4),
    ('e1c5441d-9da0-5a37-b1dd-10168cedada4'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, 'Quel est le participe passé de « volver » ?', 'mcq', '["Vuelto","Volvido","Volvido/vuelto","Voltado"]'::jsonb, 0, 'Comme *resolver → resuelto*, *poner → puesto*.', 5),
    ('8bdcd9bf-c9c4-5e29-8854-208d02adb434'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, 'L’espagnol emploie la passive avec « ser » plus souvent que le français.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il lui préfère la tournure *se* ou la 3e personne du pluriel.', 6),
    ('7e155a15-2438-5b0c-b89c-4a350d5b3de1'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, 'Quel participe emploie-t-on comme adjectif avec « freír » ?', 'mcq', '["Frito (patatas fritas)","Freído","Freito","Fritado"]'::jsonb, 0, 'Participe double : *he freído* aux temps composés, *frito* comme adjectif.', 7),
    ('79c7878b-beb8-5118-926d-7c7e3385f7e7'::uuid, 'b3374b76-1069-50d1-bfbf-27a7929d8cb0'::uuid, 'Quel est le participe passé de « satisfacer » ?', 'mcq', '["Satisfecho","Satisfacido","Satisfaído","Satisfacto"]'::jsonb, 0, 'Formé sur *hacer → hecho*.', 8),
    ('10f8aff7-d171-5166-a622-4ec468bb5c33'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, 'Dans « Me gustan las películas », quel est le sujet ?', 'mcq', '["Las películas","Me","Yo","Gustan"]'::jsonb, 0, 'Le verbe s’accorde avec ce qui plaît, pas avec la personne.', 1),
    ('1ed0678b-769f-539f-8139-d52ec49ad68f'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, 'Comment traduire « j’aime lire et écrire » ?', 'mcq', '["Me gusta leer y escribir","Me gustan leer y escribir","Yo gusto leer y escribir","Me gusto leer y escribir"]'::jsonb, 0, 'Un ou plusieurs infinitifs comptent pour un singulier.', 2),
    ('ea752c37-7b51-5252-a6cb-697a7003c499'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, '« A mí me gusta » est une redondance à éviter.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la norme : le *a mí* renforce, le pronom *me* reste obligatoire.', 3),
    ('53e524d2-a3b1-546e-b359-6f9114e48da6'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, 'Comment traduire « j’ai mal à la tête » ?', 'mcq', '["Me duele la cabeza","Duelo la cabeza","Tengo dolor la cabeza","Me duelo la cabeza"]'::jsonb, 0, '*Doler* se construit comme *gustar*.', 4),
    ('6b6e18c0-cde2-5da9-912e-4626edaa616c'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, 'Que répondre à « Me gusta el cine » pour dire « moi aussi » ?', 'mcq', '["A mí también","A mí tampoco","A mí sí","Yo también gusto"]'::jsonb, 0, '*Tampoco* servirait à répondre à une phrase négative.', 5),
    ('98e29056-bee2-519f-b941-2422fa14f0e3'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, '« Me encantan los perros » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Encantar* fonctionne comme *gustar* : accord avec *los perros*.', 6),
    ('6e48a885-306e-527b-9e6e-8153e3b8c401'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, 'Comment renforcer « le gusta » pour préciser qu’il s’agit de Juan ?', 'mcq', '["A Juan le gusta","Juan le gusta","Le gusta Juan","A Juan gusta"]'::jsonb, 0, 'Le pronom *le* se maintient même quand le nom est exprimé.', 7),
    ('b4eb460f-26f7-52a2-a5a7-74831eb3f193'::uuid, '274b7b34-5728-5504-979b-e75b5c78922d'::uuid, 'On peut dire « me gusta muy ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On dit *me gusta mucho* : *muy* ne modifie jamais un verbe.', 8),
    ('89a46294-6e0d-5219-8a3b-048abd4ae5cf'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, 'Quelle tournure exprime une obligation personnelle ?', 'mcq', '["Tener que + infinitif","Hay que + infinitif","Soler + infinitif","Acabar de + infinitif"]'::jsonb, 0, '*Tengo que estudiar* : l’obligation vise quelqu’un.', 1),
    ('a78ad3da-f077-5924-9056-42f2fb53c93b'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, '« Hay que » est invariable.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’obligation est impersonnelle : aucun sujet, donc aucune variation en personne.', 2),
    ('8f5befb9-748e-5982-8fe0-bbb9744d542c'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, 'Que signifie « Debe de estar enfermo » ?', 'mcq', '["Il doit être malade (supposition)","Il doit rester malade","Il faut qu’il soit malade","Il a dû tomber malade"]'::jsonb, 0, '*Deber de* exprime la probabilité, *deber* seul l’obligation morale.', 3),
    ('0a58ff96-29fa-5744-884f-06f7880922e1'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, 'Comment traduire « il faut étudier » (en général) ?', 'mcq', '["Hay que estudiar","Tengo que estudiar","Debo estudiar","Es estudiar"]'::jsonb, 0, 'L’obligation impersonnelle passe par *hay que*.', 4),
    ('261625f3-5e63-5ece-9b6f-07e50ddee615'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, 'Après « Es necesario que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Es necesario que vengas* : le jugement impersonnel commande le subjonctif.', 5),
    ('9f914103-181b-5639-bbb2-6ee4308e7701'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, 'Quelle nuance sépare « tenía que estudiar » et « tuve que estudiar » ?', 'mcq', '["L’imparfait laisse ouvert, le passé simple conclut","Aucune","Le premier est un futur","Le second est impersonnel"]'::jsonb, 0, '*Tuve que* dit que l’obligation a été suivie d’effet.', 6),
    ('179fef75-d1d9-5679-9b7f-4901bddbc582'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, '« Haber de + infinitif » appartient à un registre soutenu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*He de irme* : obligation atténuée, plus littéraire que *tengo que*.', 7),
    ('b61130db-f03a-5dcd-849c-31da0c248db0'::uuid, '59105554-e03f-5c5f-b8bc-6f0905128ac4'::uuid, 'Comment exprimer un ordre direct ?', 'mcq', '["Par l’impératif : ¡Estudia!","Par le gérondif","Par l’infinitif seul","Par le futur"]'::jsonb, 0, 'Et à la forme négative, l’impératif emprunte au subjonctif : *¡No salgas!*', 8),
    ('9a1f2cfc-362f-5501-a0f5-8b3005c74778'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, 'Que signifie « Suelo levantarme temprano » ?', 'mcq', '["J’ai l’habitude de me lever tôt","Je me lève seul","Je viens de me lever","Je dois me lever tôt"]'::jsonb, 0, '*Soler* + infinitif exprime l’habitude à lui seul.', 1),
    ('fe63bb43-bf87-5ba3-9099-f76fa1dfbfad'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, 'À quels temps « soler » s’emploie-t-il ?', 'mcq', '["Au présent et à l’imparfait","À tous les temps","Au passé simple seulement","Au futur seulement"]'::jsonb, 0, 'L’habitude n’est pas un événement daté : ni passé simple, ni futur.', 2),
    ('52453d01-85d5-5e4f-807f-56ce163bdee0'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, '« Soler » est un verbe à diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Suelo, sueles, suele… solemos, soléis, suelen.*', 3),
    ('37db21cf-7793-560b-95dd-63644a30b283'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, 'Comment traduire « je l’ai rappelé » (une seconde fois) ?', 'mcq', '["Volví a llamarlo","Rellamé","Llamé otra vez lo","Vuelvo llamarlo"]'::jsonb, 0, '*Volver a* + infinitif remplace le préfixe « re- » du français.', 4),
    ('a9fb5ad6-a030-581f-96c9-b0b92d13b9b3'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, '« Acostumbrarse a » signifie « avoir l’habitude de ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La forme pronominale signifie « s’habituer à ».', 5),
    ('1f172bcd-18df-5280-ad10-fdd64d147e98'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, 'Quel temps exprime seul l’habitude passée ?', 'mcq', '["L’imparfait","Le passé simple","Le futur","Le conditionnel"]'::jsonb, 0, '*Cuando era pequeño, jugaba al fútbol.*', 6),
    ('247b8c35-e83d-5444-9ed4-b90597553b99'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, '« De vez en cuando » signifie…', 'mcq', '["De temps en temps","Toujours","Jamais","Chaque fois"]'::jsonb, 0, 'Entre *a menudo* (souvent) et *casi nunca* (presque jamais).', 7),
    ('36a2ff50-7ba2-5c22-b4c1-8a6b644b670c'::uuid, 'c06caf9b-99cc-5708-9113-d9ae9cf86ac8'::uuid, '« Seguir + gérondif » exprime la continuation d’une action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sigo estudiando español* : je continue d’étudier l’espagnol.', 8),
    ('98442327-a11f-5b4a-acea-4ea081edac21'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, 'Que signifie « Serán las tres » ?', 'mcq', '["Il doit être trois heures","Il sera trois heures","Il était trois heures","Il faut qu’il soit trois heures"]'::jsonb, 0, 'Le futur de probabilité suppose sur le PRÉSENT.', 1),
    ('38d77185-6505-558a-801c-b75bf93ed67e'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, 'Le conditionnel de probabilité porte sur…', 'mcq', '["Le passé","Le présent","Le futur","L’avenir proche"]'::jsonb, 0, '*Serían las tres cuando llegó* : il devait être trois heures.', 2),
    ('5d9f722a-664f-5c54-a41a-dfd89e859a53'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, '« Puede que » est suivi du subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Puede que llueva* — sans exception.', 3),
    ('768d8b09-1876-58a6-a174-3f6da6fec30c'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, 'Quel mode suit « a lo mejor » ?', 'mcq', '["L’indicatif","Le subjonctif","L’infinitif","Le gérondif"]'::jsonb, 0, 'C’est le piège : à la différence de *quizás*, *a lo mejor* garde l’indicatif.', 4),
    ('b9fed989-dfb0-58b3-92f7-a2e62d6f36d5'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, '« Debe estudiar » et « Debe de estudiar » ont le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier exprime l’obligation, le second la supposition.', 5),
    ('d12ad2e6-1988-5c7e-a026-03784d2063fd'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, '« Quizás venga » plutôt que « quizás viene » signale…', 'mcq', '["Une probabilité plus faible","Une certitude","Un ordre","Un futur proche"]'::jsonb, 0, 'Le subjonctif marque la réserve, l’indicatif l’assurance.', 6),
    ('76234b89-5c65-58d4-b95f-9e9a8b687c93'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, '« Habrá salido » suppose sur un fait accompli.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur antérieur de probabilité : il a dû sortir.', 7),
    ('93a73d19-7b08-5bc2-a63d-9fca9bcde2ec'::uuid, '3290a18f-7075-50c0-8131-c721d71ab5dc'::uuid, 'Comment traduire « il devait avoir vingt ans » ?', 'mcq', '["Tendría veinte años","Tendrá veinte años","Tuvo veinte años","Tenía que tener veinte años"]'::jsonb, 0, 'Conditionnel de probabilité, pour supposer sur le passé.', 8),
    ('5a2b16f6-a689-5b50-99e0-a813fd748c5e'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, 'Comment forme-t-on l’impératif négatif ?', 'mcq', '["Avec le subjonctif présent","Avec l’impératif affirmatif précédé de no","Avec l’infinitif","Avec le futur"]'::jsonb, 0, '*No hables*, *no comas*, *no salgáis*.', 1),
    ('72340bc0-3680-54b4-93fc-440d7e5914e1'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, 'Quel est l’impératif de « hacer » à la deuxième personne du singulier ?', 'mcq', '["Haz","Hace","Haga","Haced"]'::jsonb, 0, 'Comme *di*, *ve*, *pon*, *sal*, *sé*, *ten*, *ven*.', 2),
    ('589a486c-a88a-5751-ac78-f26d47ae2e5d'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, 'Après « Te aconsejo que », le verbe est au subjonctif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Te aconsejo que vayas al médico.*', 3),
    ('fe9bd59d-b88c-537e-a5eb-a7a97b4f85a9'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, 'Comment traduire « tu devrais te reposer » ?', 'mcq', '["Deberías descansar","Debes descansar","Debías descansar","Debe de descansar"]'::jsonb, 0, 'Le conditionnel atténue l’obligation en conseil.', 4),
    ('f2044ca9-9bf3-53e4-bd5c-061c71079527'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, '« Ojalá pudiera ayudarte » exprime un souhait réalisable.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’imparfait du subjonctif marque au contraire l’improbable.', 5),
    ('c9801120-ae6f-5ad3-815e-4245a3deb557'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, 'Que signifie « Yo que tú, iría al médico » ?', 'mcq', '["À ta place, j’irais chez le médecin","Moi et toi allons chez le médecin","Je te vois chez le médecin","Je dois aller chez le médecin"]'::jsonb, 0, 'La tournure se poursuit au conditionnel.', 6),
    ('03d0d99e-7dde-5adf-aacb-9d5ff055c556'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, 'L’impératif affirmatif soude les pronoms au verbe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Dímelo* ; au négatif, ils repassent devant : *no me lo digas*.', 7),
    ('2a060b29-e8f7-54e9-ae2d-bdb11e2ed900'::uuid, '9f72bb43-f5eb-5ff3-b549-92bfda3c6858'::uuid, 'Quel mode suit « ¿Y si… ? » pour suggérer ?', 'mcq', '["L’indicatif","Le subjonctif","L’impératif","Le conditionnel"]'::jsonb, 0, '*¿Y si salimos esta noche?*', 8),
    ('d38e36b0-e5b1-5ecb-8a97-3c16feeea3f8'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, 'Quelle est la première personne du présent de « hacer » ?', 'mcq', '["Hago","Haco","Hazo","Hacio"]'::jsonb, 0, 'Verbe à *yo* irrégulier : le reste de la conjugaison est régulier.', 1),
    ('e1c3c1e4-23b6-5ba0-a801-373b421c8764'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, 'Quelle est la première personne du présent de « conocer » ?', 'mcq', '["Conozco","Conoco","Conosco","Conogo"]'::jsonb, 0, 'Comme tous les verbes en -cer et -cir : *parezco*, *conduzco*.', 2),
    ('906e93a8-9872-5316-a86c-8226be2cfad9'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, '« Ser », « ir », « haber » et « estar » sont totalement irréguliers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Soy*, *voy*, *he*, *estoy* : aucune ne suit un modèle.', 3),
    ('5a7a2a15-f56e-5df6-9ba7-b32317947750'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, 'Que signifie « Estudio español desde hace dos años » ?', 'mcq', '["J’étudie l’espagnol depuis deux ans","J’ai étudié l’espagnol il y a deux ans","J’étudierai deux ans","J’étudiais depuis deux ans"]'::jsonb, 0, 'Le présent couvre l’action commencée dans le passé et qui dure.', 4),
    ('4217ed19-7f6d-5c99-a424-f13f78ca4ca1'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, '« Tener » cumule un yo irrégulier et une diphtongue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Tengo*, puis *tienes, tiene… tenemos, tenéis, tienen*.', 5),
    ('a0c790fd-2ac2-5643-bdbf-9b499e0aa70a'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, 'Pourquoi « estás » porte-t-il un accent écrit ?', 'mcq', '["L’accent tonique tombe sur la terminaison","C’est un pluriel","Pour le distinguer de « estas »","C’est un subjonctif"]'::jsonb, 0, 'Le second motif est vrai aussi, mais la raison première est prosodique.', 6),
    ('f89b8ad0-383d-53a7-93a0-7083c717582c'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, 'Les verbes en -er et en -ir se conjuguent identiquement au présent, sauf…', 'mcq', '["À nosotros et vosotros","À yo et tú","À él et ellos","Nulle part"]'::jsonb, 0, '*Comemos / vivimos*, *coméis / vivís*.', 7),
    ('b5ee9805-5d54-5b6a-b815-cba4a9d58aca'::uuid, '787dc197-d884-5e0c-9393-7f3bbc6e7fd7'::uuid, 'Le présent peut exprimer un futur proche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mañana salgo a las ocho.*', 8),
    ('82833a1a-a929-56a1-a3d6-f05fee755760'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, 'De quelle forme part-on pour construire le subjonctif présent ?', 'mcq', '["De la première personne du présent de l’indicatif","De l’infinitif","Du participe passé","Du passé simple"]'::jsonb, 0, 'On retire le -o et on inverse la voyelle des terminaisons.', 1),
    ('50678e88-54da-561f-bbfc-3829f97ae9d6'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, 'Quelle voyelle prennent les terminaisons du subjonctif des verbes en -ar ?', 'mcq', '["E (hable, hables…)","A","I","O"]'::jsonb, 0, 'Et inversement, les -er et -ir prennent un a : *coma, comas*.', 2),
    ('dd894956-71ce-5d16-938d-7d68d1f8b172'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, 'Quel est le subjonctif présent de « tener » à la première personne ?', 'mcq', '["Tenga","Tena","Tienga","Tuviera"]'::jsonb, 0, 'Il hérite du *yo* irrégulier : *tengo → tenga*.', 3),
    ('61ec8f60-93b6-5470-bc12-b7030f468e07'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, 'Après « Cuando » suivi d’une valeur de futur, on emploie…', 'mcq', '["Le subjonctif","Le futur","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — piège majeur du francophone.', 4),
    ('ec60169f-8c19-5528-8ac7-72746d247783'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, '« Ser », « ir », « haber », « saber », « dar » et « estar » ont un subjonctif irrégulier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Sea*, *vaya*, *haya*, *sepa*, *dé*, *esté*.', 5),
    ('46615271-cba1-56f5-b4c9-fc8444d836bd'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, 'Au subjonctif, l’affaiblissement touche « nosotros » et « vosotros ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pidamos*, *pidáis* — contrairement à la diphtongue.', 6),
    ('d2b934b1-1f2f-51a8-acb6-d6134e79f696'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, 'Quelle conjonction est toujours suivie du subjonctif ?', 'mcq', '["Para que","Porque","Aunque toujours","Ya que"]'::jsonb, 0, 'Comme *antes de que*, *sin que*, *a menos que*.', 7),
    ('eff199bd-7067-50f4-b259-9f769ae88742'::uuid, 'bf11cd7a-d44f-5225-aaaa-2163b36a7143'::uuid, 'Quel est le subjonctif présent de « ir » ?', 'mcq', '["Vaya","Vaiga","Iría","Fuera"]'::jsonb, 0, 'L’un des six irréguliers dont la 1re personne ne finit pas par -o.', 8),
    ('8baf5aed-17f1-52de-8924-f9fb3a013f97'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, 'Combien de verbes sont irréguliers à l’imparfait ?', 'mcq', '["Trois : ser, ir, ver","Aucun","Six","Dix"]'::jsonb, 0, '*Era*, *iba*, *veía* — la seule liste courte de la conjugaison espagnole.', 1),
    ('0f03e27f-7e55-5082-a1e7-ce9620ecb91c'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, 'Quelle est la terminaison de l’imparfait des verbes en -ar ?', 'mcq', '["-aba","-ía","-ió","-aría"]'::jsonb, 0, 'Les -er et -ir font *-ía*.', 2),
    ('e5a251be-4015-5909-942d-e62cccd93f92'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, '« Cuando era pequeño, jugaba al fútbol » exprime une habitude.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’emploi principal de l’imparfait avec la description.', 3),
    ('c34f2b29-f908-58cd-ba48-7e32939fba4d'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, 'Dans « Llovía cuando salí », quel temps fait avancer l’action ?', 'mcq', '["Salí (passé simple)","Llovía (imparfait)","Les deux","Aucun"]'::jsonb, 0, 'L’imparfait pose le décor, le passé simple marque l’événement.', 4),
    ('f192410e-6aee-55eb-bc5d-a754c3448f16'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, 'Quel est l’imparfait de « ver » ?', 'mcq', '["Veía","Vía","Veaba","Vía/vea"]'::jsonb, 0, 'Il se forme sur l’ancien infinitif *veer*.', 5),
    ('7200c642-bacc-5208-a95c-d5fc905fa4c2'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, '« Ayer llovió » et « Ayer llovía » disent exactement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier rapporte un fait, le second décrit un contexte.', 6),
    ('d3a08439-ccde-58fd-a517-982ecbd59906'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, 'Que signifie « Quería pedirle un favor » dans une demande polie ?', 'mcq', '["Je voudrais vous demander un service","Je voulais et je ne veux plus","J’ai demandé un service","Je devrai demander un service"]'::jsonb, 0, 'L’imparfait de politesse atténue la demande.', 7),
    ('c5e1adc7-2bec-5a58-bf7f-8364e74153d6'::uuid, '20854cd9-550c-54f0-aac7-e5f7d2f062e1'::uuid, 'L’imparfait peut exprimer une action en cours interrompue par une autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mientras cenábamos, sonó el teléfono.*', 8),
    ('67ba92e1-2a3a-5d15-9122-36ade0d692eb'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, 'Comment se forme le pretérito perfecto ?', 'mcq', '["Haber au présent + participe passé","Tener + participe passé","Ser + participe passé","Estar + gérondif"]'::jsonb, 0, '*He comido*, *has estudiado*.', 1),
    ('1eabfc4b-6216-554a-8c75-9d3559e28307'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, 'Quel marqueur appelle le pretérito perfecto ?', 'mcq', '["Hoy","Ayer","El año pasado","En 1990"]'::jsonb, 0, 'Comme *esta semana*, *este año*, *ya*, *todavía no*.', 2),
    ('f0f39dd1-b96e-5d34-824b-065d61731675'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, 'Le participe passé s’accorde avec le sujet au pretérito perfecto.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec *haber*, jamais d’accord : *ellas han llegado*.', 3),
    ('60977ad6-4195-5769-9f62-24fa59a90197'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, '« Este año he viajado mucho » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période n’est pas achevée : le passé composé s’impose.', 4),
    ('8c95b9e9-56d2-57f8-8595-193c2bfcdb83'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, 'Quelle est la différence entre « Hoy he ido al cine » et « Ayer fui al cine » ?', 'mcq', '["Le premier appartient à une période non achevée","Aucune","Le premier est plus soutenu","Le second est un plus-que-parfait"]'::jsonb, 0, 'Le passé simple coupe du présent, le passé composé raccroche.', 5),
    ('ae584552-0516-5726-82a1-4ad92348a8e4'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, 'En Amérique latine, le passé simple absorbe souvent le passé composé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hoy comí paella* y est courant, sans être une faute.', 6),
    ('41b7583d-2738-5d63-b89e-f643933bdd09'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, 'Que peut-on intercaler entre « haber » et le participe ?', 'mcq', '["Rien","Un adverbe","Une négation","Un pronom"]'::jsonb, 0, 'Le bloc est soudé : *No lo he visto nunca*.', 7),
    ('fb553481-627d-5000-8847-ec17b72013b5'::uuid, 'da2ff5f3-a4e2-5d2b-b9e9-2a2fb2e9027c'::uuid, '« Nunca he estado en México » est un bilan de vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période de référence est la vie entière, non achevée.', 8),
    ('2021ab98-c77a-5176-9510-937b60c74120'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, 'Quelles terminaisons prend le passé simple des verbes en -ar ?', 'mcq', '["-é, -aste, -ó, -amos, -asteis, -aron","-í, -iste, -ió…","-aba, -abas…","-aré, -arás…"]'::jsonb, 0, '*Hablé, hablaste, habló, hablamos, hablasteis, hablaron.*', 1),
    ('3f25ae0c-8282-5176-905f-3472405ddce1'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, '« Hablo » et « habló » se distinguent uniquement par l’accent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un est un présent, l’autre un passé simple : l’accent est distinctif.', 2),
    ('a7b0a809-5f47-523d-ab17-225b1536146f'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, 'Quel est le passé simple de « tener » à la première personne ?', 'mcq', '["Tuve","Tení","Tuvé","Tenió"]'::jsonb, 0, 'Prétérit fort : radical *tuv-* et terminaisons sans accent.', 3),
    ('82c72bf3-2bb3-5476-9ecb-d3daca4d1ab3'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, 'Quelle est la troisième personne du pluriel de « decir » au passé simple ?', 'mcq', '["Dijeron","Dijieron","Decieron","Digieron"]'::jsonb, 0, 'Après un radical en -j, le i de la terminaison disparaît.', 4),
    ('4d2bf1e9-95ff-579b-b3ec-0c89f7f5b545'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, '« Ser » et « ir » ont la même forme au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Fui, fuiste, fue…* : seul le contexte permet de trancher.', 5),
    ('477aa243-eef8-5758-b818-72e276b4f64d'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, 'Quel marqueur appelle le passé simple ?', 'mcq', '["Ayer","Hoy","Esta semana","Todavía no"]'::jsonb, 0, 'Comme *anoche*, *el año pasado*, *en 1975*.', 6),
    ('87e0aeeb-599e-5506-b04c-c538251e88e4'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, 'Quelle est la troisième personne de « dormir » au passé simple ?', 'mcq', '["Durmió","Dormió","Duermió","Durmó"]'::jsonb, 0, 'Les verbes en -ir portent l’affaiblissement aux deux 3es personnes.', 7),
    ('99ce48b0-b864-5d0d-9442-6fe92d47e1a4'::uuid, '17855669-8a37-5a0a-afd5-11ef52888099'::uuid, 'Dans un récit, le passé simple fait avancer l’action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’imparfait, lui, décrit le cadre : *Era de noche… De repente, sonó el timbre.*', 8),
    ('b7031491-2794-580a-849d-8fe70054e077'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, 'Sur quoi se construit le futur simple espagnol ?', 'mcq', '["Sur l’infinitif entier","Sur le radical du présent","Sur le participe passé","Sur le passé simple"]'::jsonb, 0, '*Hablaré*, *comeré*, *viviré* : mêmes terminaisons pour les trois groupes.', 1),
    ('4bfd3359-29a5-5a56-bd01-0ee6971082a1'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, 'Quel est le futur de « tener » à la première personne ?', 'mcq', '["Tendré","Teneré","Tenré","Tendría"]'::jsonb, 0, 'Un d remplace la voyelle, comme dans *pondré*, *vendré*, *saldré*.', 2),
    ('ff3cb743-4ad6-567e-854f-651eb001e26a'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, 'Le conditionnel se forme sur le même radical que le futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec les terminaisons de l’imparfait en -ía : *tendría*, *haría*, *diría*.', 3),
    ('6095bea1-7080-54a5-acc0-720c4b6cda3c'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, 'Que met-on après « cuando » avec une valeur de futur ?', 'mcq', '["Le subjonctif présent","Le futur simple","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — jamais « cuando llegarás ».', 4),
    ('68fd77b2-a968-5af9-a96a-e322b0ee6e08'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, 'Quel est le futur de « hacer » ?', 'mcq', '["Haré","Haceré","Hará","Hicé"]'::jsonb, 0, 'Radical raccourci, comme *decir → diré*.', 5),
    ('2122d873-3061-5839-a6a9-9d6e0a8a64a9'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, '« Serán las tres » exprime une probabilité sur le présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur de supposition : il doit être trois heures.', 6),
    ('142817bb-e626-56d7-b9df-0ec54858ec8e'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, 'Quelle forme du futur ne porte pas d’accent écrit ?', 'mcq', '["Nosotros (hablaremos)","Yo","Tú","Ellos"]'::jsonb, 0, 'Toutes les autres en portent un : *hablaré, hablarás, hablará, hablaréis, hablarán*.', 7),
    ('175f5f93-fde5-5d8d-984d-b1ce0c9d4f38'::uuid, '5b714e53-70de-5b7a-9ad0-dfd0accfb434'::uuid, '« Ir a + infinitif » exprime l’intention ou l’imminence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Voy a estudiar* : le futur proche, très employé à l’oral.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('espagnol');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('espagnol')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 305 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 305 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
